function e(e){const t=e=>String(e||"").replace(/[&<>"']/g,e=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[e])),a=JSON.stringify({title:e.title,purpose:e.purpose,kind:e.kind,items:e.items||[]}).replace(/</g,"\\u003c");return`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${t(e.title)}</title><style>\nbody{max-width:880px;margin:auto;padding:32px 20px;font:16px/1.5 system-ui,sans-serif;color:#1f2937;background:#f8fafc}h1{margin-bottom:8px}small,p{color:#475569}article{display:flex;gap:12px;align-items:center;border:1px solid #cbd5e1;padding:14px;border-radius:10px;background:white;margin:10px 0}label{flex:1;min-width:0}label span{display:block;overflow-wrap:anywhere}input:not([type=checkbox]),button{padding:10px;border:1px solid #94a3b8;border-radius:6px;background:white;color:inherit;font:inherit}form{display:flex;gap:8px;flex-wrap:wrap}form input{flex:1;min-width:160px}button{cursor:pointer}.value{max-width:36%;min-width:0}.done label{text-decoration:line-through}@media(max-width:560px){article{flex-wrap:wrap}.value{max-width:none;width:100%}}</style></head><body><header><small>MoonDesk · Standalone artifact</small><h1>${t(e.title)}</h1><p>${t(e.purpose)}</p><p>This copy is independent of your MoonBook. Edit it here and download an updated copy to keep your changes.</p><button id="download">Download updated copy</button></header><main id="items"></main><form id="add"><input name="label" aria-label="New item" placeholder="Add an item" required><input name="value" aria-label="Value or note" placeholder="Value or note"><button>Add item</button></form><script id="artifact-data" type="application/json">${a}<\/script><script>\nconst state=JSON.parse(document.getElementById('artifact-data').textContent);const root=document.getElementById('items');function render(){root.replaceChildren();for(const item of state.items){const row=document.createElement('article');row.className=item.done?'done':'';const toggle=document.createElement('input');toggle.type='checkbox';toggle.checked=!!item.done;toggle.setAttribute('aria-label','Mark '+item.label+' complete');toggle.onchange=()=>{item.done=toggle.checked;render()};const label=document.createElement('label');const text=document.createElement('span');text.textContent=item.label;label.append(text);if(item.source){const source=document.createElement('small');source.textContent='Source: '+item.source;label.append(source)}const value=document.createElement('input');value.className='value';value.value=item.value||'';value.setAttribute('aria-label','Value for '+item.label);value.oninput=()=>{item.value=value.value};row.append(toggle,label,value);root.append(row)}}document.getElementById('add').onsubmit=event=>{event.preventDefault();const data=new FormData(event.target);state.items.push({label:String(data.get('label')),value:String(data.get('value')),done:false});event.target.reset();render()};document.getElementById('download').onclick=()=>{document.getElementById('artifact-data').textContent=JSON.stringify(state).replace(/</g,'\\u003c');const html='<!doctype html>'+document.documentElement.outerHTML;const url=URL.createObjectURL(new Blob([html],{type:'text/html'}));const link=document.createElement('a');link.href=url;link.download='artifact.html';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();<\/script></body></html>`}function t(t){const a=URL.createObjectURL(new Blob([e(t)],{type:"text/html;charset=utf-8"})),n=document.createElement("a");n.href=a,n.download=`${String(t.title||"artifact").replace(/[^a-z0-9\u4e00-\u9fff]+/gi,"-").replace(/^-|-$/g,"")||"artifact"}.html`,document.body.append(n),n.click(),setTimeout(()=>{n.remove(),URL.revokeObjectURL(a)},1e3)}export{t as downloadArtifact,e as standaloneArtifactHtml};
